def page(mode):
    labels=sorted({label for t in TASKS for label in t['labels']})
    filters=''.join(f'<option value="{html.escape(label)}">{html.escape(label)}</option>' for label in labels)
    mode_note='Age is time since reservation; # is attempt number.' if mode!='split' else 'Age is time since reservation, not productive work.'
    body=f'''<header class="top"><div class="row"><span class="product">colony</span><span class="divider">/</span><h1>hive <span class="divider">/</span> Active bees</h1></div><div class="row"><span class="sample">SAMPLE</span><time class="snapshot">14:32:00</time></div></header><section class="toolbar" aria-label="Filters"><label class="sr-only" for="search">Search bees and linked beads</label><input id="search" type="search" placeholder="Search bees, beads, labels…"><label class="sr-only" for="label">Task label</label><select id="label"><option value="all">All task labels</option>{filters}</select><label class="sr-only" for="attempt">Recorded attempt state</label><select id="attempt"><option value="all">All active attempts</option><option value="running">Running</option><option value="starting">Starting</option></select><button id="reset" class="reset" hidden>Clear filters</button><output id="results" class="results" aria-live="polite"></output></section><main id="content"></main><footer class="endnote"><span>{mode_note}</span><span>Recorded attempt state ≠ verified process liveness</span></footer><dialog id="bead-dialog" aria-labelledby="modal-title"><div class="row between"><span id="modal-id" class="record-caption mono"></span><button class="button" id="close-dialog" aria-label="Close bead details">Close ×</button></div><h2 id="modal-title"></h2><div id="modal-content"></div></dialog>'''
    js=SCRIPT.replace('const bees = BEES;', 'const bees = '+json.dumps(BEES)+';').replace('const tasks = TASKS;', 'const tasks = '+json.dumps(TASKS)+';').replace('const mode = MODE;', 'const mode = '+json.dumps(mode)+';')
    source='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Colony / '+mode+'</title><style>'+CSS+'</style></head><body>'+body+'<script>'+js+'</script></body></html>'
    (OUT/f'control-room-{mode}.html').write_text(source)
    return source

variants=[
    ('A · Nested ledger','ledger','Bee-first, with each bee spanning its linked bead rows. Status, priority and labels stay visible without opening anything. <strong>Best information density; closest to the original.</strong> Click a bead for acceptance criteria or a label to filter.'),
    ('B · Work lanes','lanes','One column per bee; beads are the working objects underneath. Execution metadata appears once, in the lane header. <strong>Easier to read each bee’s workload; trades horizontal space for clearer task grouping.</strong> Blocked and completed beads stay distinct from the bee’s running state.'),
    ('C · Split inspector','split','A compact bee roster keeps the selection context; the right pane spends its space on linked beads, descriptions, acceptance criteria and blockers. <strong>Best for investigating one bee without popups.</strong> Select another bee to change the context; the selected identity is not repeated in the detail pane.'),
]
body='''<p>The control-room direction, reduced to a working surface. Same six fictional bees and ten linked beads in every variant. No hero text, summary cards or decorative navigation inside the dashboards.</p><div class="tabs">'''
for i,(name,mode,description) in enumerate(variants):
    body+=f'<label class="tab"><input type="radio" name="variant" style="display:inline-block;accent-color:var(--accent)" {"checked" if i==0 else ""}>{name}</label>'
for name,mode,description in variants:
    body+=f'<div class="tab-panel"><p>{description}</p><iframe title="{name} prototype" sandbox="allow-scripts" srcdoc="{html.escape(page(mode),quote=True)}" style="display:block;width:calc(100vw - 40px);height:820px;margin:20px calc(50% - 50vw + 20px);border:1px solid #626c5c;border-radius:8px;box-shadow:0 12px 40px #0002;background:#111615"></iframe></div>'
body+='''</div><p><strong>Label policy in these mockups:</strong> show the task’s useful labels, such as <code>area:colony</code>, <code>area:shared</code>, <code>area:honeycomb</code>, <code>area:tooling</code> and <code>evidence:architecture</code>. Omit spawn bookkeeping: <code>system</code>, <code>bee</code>, <code>agent:*</code>, <code>bee-outcome:*</code> and <code>bee-resolution:*</code>. Priority, type and native status are fields, not labels.</p><p><strong>My lean:</strong> A as the default working board, with C’s inspector available on selection. B is worth keeping only if “what work is attached to each bee?” is the main scan.</p>'''
(OUT/'control-room-variants-body.html').write_text(body)
print('Generated ledger, work lanes and split inspector prototypes.')
